var l=[{title:`Ваш загальний стрес`,text:`Тренування: лише одна частина стресу, який ви несете. Поганий сон, подорожі, вимоглива робота, емоційна напруга, спека та нещодавня хвороба можуть впливати на концентрацію, координацію та те, наскільки важкою здається робота. Готовність не є діагнозом, і жоден показник не охоплює її повністю.`},{title:`Проста перевірка самопочуття`,text:`Перед тренуванням зверніть увагу на свій сон, енергію, мотивацію, болючість і будь-які нові симптоми. Порівнюйте їх із тим, що нормально для вас, а не з чужими числами. Розминка дає другу перевірку: якщо рухи несподівано здаються важкими або контроль збитий, вимогливе заняття може потребувати коригування.`},{title:`Коригування в слабкий день`,text:`У день із малою енергією зменшіть навантаження, скоротіть заняття, оберіть простіші вправи або натомість зробіть легку прогулянку. У звичайний день виконуйте план, як записано. Не перетворюйте кожен короткий спад на день відпочинку. Тенденції за кілька занять говорять більше, ніж одна оцінка.`},{title:`Хвороба і безпека`,text:`Гарячка, хвороба, що зачіпає все тіло, симптоми в грудях чи незвична задишка є причинами пропустити важке тренування і звернутися по медичну пораду. Популярна «перевірка шиї» є лише грубим правилом і не дає дозволу тренуватися під час хвороби.`},{title:`Як це працює в TrainUp`,text:`TrainUp не призначає ваги, тож навантаження ви обираєте щодня. Ваш план змінюється лише тоді, коли ви його перегенеровуєте, на основі зусилля (RPE), яке ви оцінили після кожного заняття, будь-якого болю, про який повідомили, і того, яку частину кожного тренування ви завершили.`}];var s=[{label:`CDC: рекомендації щодо сну`,url:`https://www.cdc.gov/sleep/about/`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: біль у грудях і невідкладні симптоми`,url:`https://www.nhs.uk/symptoms/chest-pain/`}];var i={sections:l,sources:s};export{i as default,l as sections,s as sources};